with valid as (select *, lower(carrier) as carrier_lower, last_day(shipped_date) as shipped_date_month_end, coalesce(carrier, 'NONE') as resolved_carrier from shipments where order_id is not null) select id, order_id, carrier, shipped_date, sum(cost) over w_grp as running_cost, percent_rank() over (partition by status order by cost desc nulls last) as cost_percent_rank, max(cost) over w_hist as shipped_date_month_end_year_max_cost from valid where delivered_date between '2023-05-01' and '2024-12-01' window w_grp as (partition by order_id order by cost, id rows between unbounded preceding and current row), w_hist as (partition by year(shipped_date_month_end), order_id);
